create table depositos (id int primary key, nombre text not null);
insert into depositos values (1,'Pompeya'),(2,'Barracas'),(3,'Avellaneda'),(4,'Pilar');
create table bultos (
  id int generated always as identity primary key,
  deposito_id int not null references depositos(id),
  estado text not null, peso_kg numeric(6,2) not null,
  creado timestamptz not null default now());
insert into bultos (deposito_id, estado, peso_kg)
select 1 + (g % 4), (array['recibido','en ruta','entregado'])[1 + (g % 3)], 1 + (g % 400) / 10.0
from generate_series(1, 300000) g;
create index on bultos (deposito_id);

